// gapsTitle is a proyecto's gaps in one line, "Falta: marcar entrega; registrar pago
// (saldo $X)", for the Etapa column of the list, where there is no room to link them.
func gapsTitle(gaps []store.ProjectGap) string {
	if len(gaps) == 0 {
		return ""
	}
	out := "Falta: "
	for i, g := range gaps {
		if i > 0 {
			out += "; "
		}
		out += g.Text
	}
	return out
}

